// Dependencies supplied by the Linux/Xen environment:
// linux/ftrace.h, xen/interface/xen.h, and xen/interface/xen-mca.h.

use core::ffi::c_char;

// The C HYPERCALL macro and the generated entries from
// <asm/xen-hypercalls.h> are build-time input.  The generated table is
// represented here as an externally supplied C-compatible array.
extern "C" {
    static xen_hypercall_names: [*const c_char; 0];
}

unsafe fn xen_hypercall_name(op: u32) -> *const c_char {
    // The array length is generated by <asm/xen-hypercalls.h> in the C
    // translation unit; its external Rust declaration preserves that
    // dependency without inventing the generated entries.
    let count = 0usize;
    if (op as usize) < count {
        let name = xen_hypercall_names[op as usize];
        if !name.is_null() {
            return name;
        }
    }

    c"".as_ptr()
}

